{
  "name": "Genova Health",
  "description": "An intelligent health companion providing AI-driven diet plans, biometrics scanning, and localized Nigerian health insights.",
  "requestFramePermissions": [
    "camera",
    "microphone",
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error("Could not find root element to mount to");

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum BloodGroup {
  A_POS = 'A+', A_NEG = 'A-', B_POS = 'B+', B_NEG = 'B-', 
  AB_POS = 'AB+', AB_NEG = 'AB-', O_POS = 'O+', O_NEG = 'O-'
}

export enum Genotype {
  AA = 'AA', AS = 'AS', SS = 'SS', AC = 'AC', SC = 'SC'
}

export interface UserProfile {
  fullName: string;
  age: number;
  bloodGroup: BloodGroup;
  genotype: Genotype;
  height: number; // in cm
  weight: number; // in kg
  allergies: string[];
  emergencyContact: string;
}

export interface HealthMetrics {
  heartRate: number;
  bloodPressure: string;
  stressLevel: 'Low' | 'Medium' | 'High';
  steps: number;
  timestamp: string;
}

export interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export enum AssistantType {
  NURSE = 'Nurse',
  NUTRITIONIST = 'Nutritionist',
  FITNESS = 'Fitness Coach',
  MENTAL = 'Wellness Coach',
  SYMPTOM_CHECKER = 'Symptom Checker'
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: (process.env.API_KEY as string) });
  }

  async getResponse(
    model: string = 'gemini-3-flash-preview',
    systemInstruction: string,
    history: Message[],
    userMessage: string
  ): Promise<string> {
    const contents = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    contents.push({
      role: 'user',
      parts: [{ text: userMessage }]
    });

    const response: GenerateContentResponse = await this.ai.models.generateContent({
      model,
      contents,
      config: {
        systemInstruction,
        temperature: 0.7,
        topP: 0.95,
      },
    });

    return response.text || "I'm sorry, I couldn't generate a response.";
  }
}

export const gemini = new GeminiService();

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { UserProfile, STORAGE_KEYS } from './types';
import Dashboard from './components/Dashboard';
import Onboarding from './components/Onboarding';
import SmartScan from './components/SmartScan';
import Assistant from './components/Assistant';
import Emergency from './components/Emergency';
import Navigation from './components/Navigation';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEYS.USER_PROFILE);
    if (stored) {
      setUser(JSON.parse(stored));
    }
    setLoading(false);
  }, []);

  const handleOnboardingComplete = (profile: UserProfile) => {
    localStorage.setItem(STORAGE_KEYS.USER_PROFILE, JSON.stringify(profile));
    setUser(profile);
  };

  if (loading) return (
    <div className="h-screen flex items-center justify-center bg-blue-50">
      <div className="text-blue-600 font-bold text-2xl animate-pulse">Genova Health...</div>
    </div>
  );

  return (
    <Router>
      <div className="min-h-screen bg-gray-50 pb-20 md:pb-0 md:pl-20">
        <Routes>
          {!user ? (
            <Route path="*" element={<Onboarding onComplete={handleOnboardingComplete} />} />
          ) : (
            <>
              <Route path="/" element={<Dashboard user={user} />} />
              <Route path="/scan" element={<SmartScan />} />
              <Route path="/assistant/:type" element={<Assistant user={user} />} />
              <Route path="/emergency" element={<Emergency />} />
              <Route path="*" element={<Navigate to="/" />} />
            </>
          )}
        </Routes>
        {user && <Navigation />}
      </div>
    </Router>
  );
};

export default App;

