import React, { useEffect, useState } from 'react';
import { UserProfile, HealthMetrics, STORAGE_KEYS } from '../types';
import { Activity, Footprints, Heart, Droplets, Utensils, Zap, ChevronRight, MapPin } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';

interface Props {
  user: UserProfile;
}

const Dashboard: React.FC<Props> = ({ user }) => {
  const [history, setHistory] = useState<HealthMetrics[]>([]);
  const [steps, setSteps] = useState(0);

  useEffect(() => {
    const storedHistory = localStorage.getItem(STORAGE_KEYS.HEALTH_HISTORY);
    if (storedHistory) {
      setHistory(JSON.parse(storedHistory));
    }

    // Simple Step Tracking Simulation for web
    const handleMotion = (event: DeviceMotionEvent) => {
      const acc = event.accelerationIncludingGravity;
      if (acc && acc.x && acc.y && acc.z) {
        const totalAcc = Math.sqrt(acc.x**2 + acc.y**2 + acc.z**2);
        if (totalAcc > 12) { // Threshold for step
          setSteps(prev => prev + 1);
        }
      }
    };

    window.addEventListener('devicemotion', handleMotion);
    return () => window.removeEventListener('devicemotion', handleMotion);
  }, []);

  const lastMetric = history[history.length - 1] || { heartRate: 72, bloodPressure: '120/80', stressLevel: 'Low' };

  return (
    <div className="p-4 md:p-10 max-w-7xl mx-auto space-y-8">
      {/* Header */}
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Welcome, {user.fullName.split(' ')[0]} 👋</h1>
          <p className="text-gray-500 font-medium">Genotype: <span className="text-blue-600">{user.genotype}</span> • Blood Group: <span className="text-red-600">{user.bloodGroup}</span></p>
        </div>
        <div className="flex gap-2">
           <div className="bg-white p-3 rounded-2xl shadow-sm border border-gray-100 flex items-center gap-3">
             <div className="p-2 bg-blue-50 text-blue-600 rounded-lg"><MapPin size={20}/></div>
             <div>
               <p className="text-[10px] text-gray-400 font-bold uppercase">Location</p>
               <p className="text-sm font-semibold">Lagos, Nigeria</p>
             </div>
           </div>
        </div>
      </header>

      {/* Metric Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <MetricCard 
          title="Heart Rate" 
          value={`${lastMetric.heartRate} BPM`} 
          sub="Resting" 
          icon={<Heart className="text-red-500" />} 
          trend="+2%"
          color="bg-red-50"
        />
        <MetricCard 
          title="Steps" 
          value={steps.toLocaleString()} 
          sub="Goal: 10,000" 
          icon={<Footprints className="text-green-500" />} 
          trend={`${Math.round((steps/10000)*100)}%`}
          color="bg-green-50"
        />
        <MetricCard 
          title="Stress Level" 
          value={lastMetric.stressLevel} 
          sub="Based on scan" 
          icon={<Zap className="text-yellow-500" />} 
          trend="Normal"
          color="bg-yellow-50"
        />
        <MetricCard 
          title="Blood Pressure" 
          value={lastMetric.bloodPressure} 
          sub="Latest check" 
          icon={<Activity className="text-blue-500" />} 
          trend="Steady"
          color="bg-blue-50"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Activity Chart */}
        <div className="lg:col-span-2 bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold">Health Activity</h2>
            <select className="bg-gray-50 border-none rounded-lg text-sm font-semibold px-3 py-1">
              <option>Last 7 Days</option>
              <option>Monthly</option>
            </select>
          </div>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorHr" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} dy={10} />
                <YAxis hide />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Area type="monotone" dataKey="hr" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorHr)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Quick Actions / AI Coaches */}
        <div className="space-y-6">
          <h2 className="text-xl font-bold">Your Genova AI Coaches</h2>
          <div className="grid grid-cols-1 gap-4">
             <CoachLink name="Nurse Genova" sub="Medical Triage & FAQ" icon={<Droplets size={20}/>} to="/assistant/nurse" color="text-blue-600" bg="bg-blue-50"/>
             <CoachLink name="Nutritionist" sub="AS/SS Genotype Diets" icon={<Utensils size={20}/>} to="/assistant/nutritionist" color="text-orange-600" bg="bg-orange-50"/>
             <CoachLink name="Wellness Coach" sub="Stress & Mental Health" icon={<Activity size={20}/>} to="/assistant/mental" color="text-purple-600" bg="bg-purple-50"/>
