const chartData = [
  { name: 'Mon', hr: 65 },
  { name: 'Tue', hr: 72 },
  { name: 'Wed', hr: 68 },
  { name: 'Thu', hr: 85 },
  { name: 'Fri', hr: 77 },
  { name: 'Sat', hr: 64 },
