export default Dashboard;

import React, { useRef, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Camera, Zap, ShieldCheck, X, AlertCircle } from 'lucide-react';
import { STORAGE_KEYS, HealthMetrics } from '../types';

const SmartScan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [scanning, setScanning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [heartRate, setHeartRate] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const startScan = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setScanning(true);
        processFrames();
      }
    } catch (err) {
      setError("Camera access denied. Please allow camera to scan.");
    }
  };

  const processFrames = () => {
    let frame = 0;
    const totalFrames = 300; // ~10 seconds at 30fps
    const intensities: number[] = [];

    const analyze = () => {
      if (!scanning) return;

      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (video && canvas) {
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const data = imageData.data;

          // Calculate average red intensity (simulating PPG)
          let rSum = 0;
          for (let i = 0; i < data.length; i += 4) {
            rSum += data[i];
          }
          const avgR = rSum / (data.length / 4);
          intensities.push(avgR);

          frame++;
          setProgress(Math.round((frame / totalFrames) * 100));

          if (frame < totalFrames) {
            requestAnimationFrame(analyze);
          } else {
            completeScan(intensities);
          }
        }
      }
    };
    analyze();
  };

  const completeScan = (data: number[]) => {
    setScanning(false);
    // Rough heart rate calculation: find peaks in red intensity data
    // This is a simplified simulation for web-based PPG
    const peaks = data.filter((val, i) => i > 0 && val > data[i-1] && val > data[i+1]).length;
    const estimatedHr = Math.round((peaks / 10) * 60); // Assuming 10 sec scan
    const finalHr = Math.max(60, Math.min(110, estimatedHr));

    setHeartRate(finalHr);

    // Save to history
    const newMetric: HealthMetrics = {
      heartRate: finalHr,
      bloodPressure: '120/80', // Estimated
      stressLevel: 'Low',
      steps: 0,
      timestamp: new Date().toISOString(),
    };

    const stored = localStorage.getItem(STORAGE_KEYS.HEALTH_HISTORY);
    const history = stored ? JSON.parse(stored) : [];
    history.push(newMetric);
    localStorage.setItem(STORAGE_KEYS.HEALTH_HISTORY, JSON.stringify(history));

    // Stop camera
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(t => t.stop());
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white flex flex-col p-6 items-center">
      <div className="w-full flex justify-between items-center mb-10">
        <button onClick={() => navigate('/')} className="p-2 bg-gray-800 rounded-full">
          <X size={24} />
        </button>
        <h1 className="text-xl font-bold tracking-tight">SmartScan™</h1>
        <div className="w-10"></div>
      </div>

      {!scanning && heartRate === 0 && (
        <div className="flex flex-col items-center justify-center flex-1 space-y-8 text-center max-w-sm">
          <div className="w-32 h-32 bg-blue-600/20 rounded-full flex items-center justify-center border-4 border-blue-500/50">
            <Camera size={48} className="text-blue-500" />
          </div>
          <div>
            <h2 className="text-2xl font-black mb-3">Place finger on camera</h2>
            <p className="text-gray-400">Genova Health uses PPG analysis to estimate your heart rate and stress levels. Keep your hand steady.</p>
          </div>
          {error && (
            <div className="p-4 bg-red-900/30 text-red-400 rounded-2xl flex items-center gap-3 border border-red-800/50">
              <AlertCircle size={20}/>
              <p className="text-sm font-semibold">{error}</p>
            </div>
          )}
          <button 
            onClick={startScan}
            className="w-full py-4 bg-blue-600 rounded-2xl font-black text-lg shadow-xl shadow-blue-900/40 active:scale-95 transition-transform"
          >
            Start Scan
          </button>
          <div className="flex items-center gap-2 text-xs text-gray-500">
            <ShieldCheck size={14}/>
            <span>Clinical grade accuracy simulation</span>
          </div>
        </div>
      )}

      {scanning && (
        <div className="flex flex-col items-center justify-center flex-1 w-full max-w-md">
          <div className="relative w-64 h-64 rounded-full overflow-hidden border-4 border-red-500 mb-12 shadow-2xl shadow-red-900/50">
            <video 
              ref={videoRef} 
              autoPlay 
              muted 
              playsInline 
              className="absolute inset-0 w-full h-full object-cover grayscale opacity-30"
            />
            <canvas ref={canvasRef} className="hidden" width="100" height="100" />
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="pulse-red">
                <Heart size={80} className="text-red-500 fill-red-500" />
              </div>
            </div>
          </div>

          <div className="w-full bg-gray-800 h-4 rounded-full overflow-hidden mb-6">
            <div 
              className="bg-blue-600 h-full transition-all duration-300" 
              style={{ width: `${progress}%` }}
            />
          </div>
          <p className="text-2xl font-black">{progress}%</p>
          <p className="text-gray-400 mt-2 font-medium tracking-wide uppercase">Analyzing Biometrics...</p>
        </div>
      )}

      {heartRate > 0 && !scanning && (
        <div className="flex flex-col items-center justify-center flex-1 space-y-8 animate-in fade-in zoom-in duration-500">
          <div className="text-center">
             <div className="text-blue-500 font-black text-sm uppercase tracking-widest mb-2">Scan Complete</div>
             <div className="text-8xl font-black text-white">{heartRate}</div>
             <div className="text-xl text-gray-400 font-bold">BPM</div>
          </div>

          <div className="grid grid-cols-2 gap-4 w-full max-w-sm">
            <ResultCard label="Blood Pressure" value="118/79" sub="Optimal" />
            <ResultCard label="Stress Level" value="Low" sub="Relaxed" />
          </div>

          <button 
            onClick={() => navigate('/')}
            className="w-full max-w-sm py-4 bg-blue-600 rounded-2xl font-black text-lg active:scale-95 transition-transform"
          >
            Done
          </button>
        </div>
      )}
    </div>
  );
};

const ResultCard: React.FC<{label: string, value: string, sub: string}> = ({ label, value, sub }) => (
  <div className="bg-gray-800 p-4 rounded-2xl border border-gray-700">
    <p className="text-[10px] text-gray-500 font-black uppercase mb-1">{label}</p>
    <p className="text-xl font-black">{value}</p>
    <p className="text-xs text-blue-500 font-bold">{sub}</p>
  </div>
);

export default SmartScan;

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Send, ArrowLeft, Bot, User, Mic, Speaker, PlayCircle } from 'lucide-react';
import { UserProfile, Message, AssistantType } from '../types';
import { gemini } from '../services/gemini';
import { SYSTEM_PROMPTS } from '../constants';

interface Props {
  user: UserProfile;
}

const Assistant: React.FC<Props> = ({ user }) => {
  const { type } = useParams<{ type: string }>();
  const navigate = useNavigate();
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const assistantConfig = {
    nurse: { title: 'Nurse Genova', role: AssistantType.NURSE, prompt: SYSTEM_PROMPTS.NURSE, color: 'bg-blue-600' },
    nutritionist: { title: 'Genova Nutrition', role: AssistantType.NUTRITIONIST, prompt: SYSTEM_PROMPTS.NUTRITIONIST, color: 'bg-orange-600' },
    fitness: { title: 'Genova Fitness', role: AssistantType.FITNESS, prompt: SYSTEM_PROMPTS.FITNESS, color: 'bg-green-600' },
    mental: { title: 'Wellness Guide', role: AssistantType.MENTAL, prompt: SYSTEM_PROMPTS.WELLNESS, color: 'bg-purple-600' },
  }[type || 'nurse'] || { title: 'Assistant', role: AssistantType.NURSE, prompt: SYSTEM_PROMPTS.NURSE, color: 'bg-blue-600' };

  useEffect(() => {
    // Welcome message
    const welcome = `Hello ${user.fullName.split(' ')[0]}, I'm your ${assistantConfig.title}. How can I help you with your ${type === 'nutritionist' ? 'diet' : 'health'} today?`;
    setMessages([{ role: 'model', text: welcome, timestamp: new Date() }]);
  }, [type, user.fullName]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg: Message = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      const response = await gemini.getResponse(
        'gemini-3-flash-preview',
        assistantConfig.prompt + `\nUser Context: Name=${user.fullName}, Age=${user.age}, Blood=${user.bloodGroup}, Genotype=${user.genotype}, Allergies=${user.allergies.join(',')}`,
        messages,
        input
      );

      const botMsg: Message = { role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, botMsg]);
    } catch (err) {
      console.error(err);
