import React, { useRef, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
// Fix: Added Heart to the imports from lucide-react
import { Camera, Zap, ShieldCheck, X, AlertCircle, Heart } from 'lucide-react';
// Fix: Only import types from types.ts
