const SmartScan: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [scanning, setScanning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [heartRate, setHeartRate] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const startScan = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setScanning(true);
        processFrames();
      }
    } catch (err) {
      setError("Camera access denied. Please allow camera to scan.");
    }
  };

  const processFrames = () => {
    let frame = 0;
    const totalFrames = 300; // ~10 seconds at 30fps
    const intensities: number[] = [];

    const analyze = () => {
      if (!scanning) return;

      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (video && canvas) {
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const data = imageData.data;

          // Calculate average red intensity (simulating PPG)
          let rSum = 0;
          for (let i = 0; i < data.length; i += 4) {
            rSum += data[i];
          }
          const avgR = rSum / (data.length / 4);
          intensities.push(avgR);

          frame++;
          setProgress(Math.round((frame / totalFrames) * 100));

          if (frame < totalFrames) {
            requestAnimationFrame(analyze);
          } else {
            completeScan(intensities);
          }
        }
      }
    };
    analyze();
  };

  const completeScan = (data: number[]) => {
    setScanning(false);
    // Rough heart rate calculation: find peaks in red intensity data
    // This is a simplified simulation for web-based PPG
    const peaks = data.filter((val, i) => i > 0 && val > data[i-1] && val > data[i+1]).length;
    const estimatedHr = Math.round((peaks / 10) * 60); // Assuming 10 sec scan
    const finalHr = Math.max(60, Math.min(110, estimatedHr));

    setHeartRate(finalHr);

    // Save to history
    const newMetric: HealthMetrics = {
      heartRate: finalHr,
      bloodPressure: '120/80', // Estimated
      stressLevel: 'Low',
      steps: 0,
      timestamp: new Date().toISOString(),
    };

    const stored = localStorage.getItem(STORAGE_KEYS.HEALTH_HISTORY);
    const history = stored ? JSON.parse(stored) : [];
    history.push(newMetric);
    localStorage.setItem(STORAGE_KEYS.HEALTH_HISTORY, JSON.stringify(history));

    // Stop camera
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(t => t.stop());
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white flex flex-col p-6 items-center">
      <div className="w-full flex justify-between items-center mb-10">
