        <h1 className="text-xl font-bold tracking-tight">SmartScan™</h1>
        <div className="w-10"></div>
      </div>

      {!scanning && heartRate === 0 && (
        <div className="flex flex-col items-center justify-center flex-1 space-y-8 text-center max-w-sm">
          <div className="w-32 h-32 bg-blue-600/20 rounded-full flex items-center justify-center border-4 border-blue-500/50">
            <Camera size={48} className="text-blue-500" />
          </div>
          <div>
            <h2 className="text-2xl font-black mb-3">Place finger on camera</h2>
            <p className="text-gray-400">Genova Health uses PPG analysis to estimate your heart rate and stress levels. Keep your hand steady.</p>
          </div>
          {error && (
            <div className="p-4 bg-red-900/30 text-red-400 rounded-2xl flex items-center gap-3 border border-red-800/50">
              <AlertCircle size={20}/>
              <p className="text-sm font-semibold">{error}</p>
            </div>
          )}
          <button 
            onClick={startScan}
            className="w-full py-4 bg-blue-600 rounded-2xl font-black text-lg shadow-xl shadow-blue-900/40 active:scale-95 transition-transform"
          >
            Start Scan
          </button>
          <div className="flex items-center gap-2 text-xs text-gray-500">
            <ShieldCheck size={14}/>
            <span>Clinical grade accuracy simulation</span>
          </div>
        </div>
      )}

      {scanning && (
        <div className="flex flex-col items-center justify-center flex-1 w-full max-w-md">
          <div className="relative w-64 h-64 rounded-full overflow-hidden border-4 border-red-500 mb-12 shadow-2xl shadow-red-900/50">
            <video 
              ref={videoRef} 
              autoPlay 
              muted 
              playsInline 
              className="absolute inset-0 w-full h-full object-cover grayscale opacity-30"
            />
            <canvas ref={canvasRef} className="hidden" width="100" height="100" />
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="pulse-red">
                <Heart size={80} className="text-red-500 fill-red-500" />
              </div>
            </div>
          </div>

          <div className="w-full bg-gray-800 h-4 rounded-full overflow-hidden mb-6">
            <div 
              className="bg-blue-600 h-full transition-all duration-300" 
              style={{ width: `${progress}%` }}
            />
          </div>
          <p className="text-2xl font-black">{progress}%</p>
          <p className="text-gray-400 mt-2 font-medium tracking-wide uppercase">Analyzing Biometrics...</p>
        </div>
      )}

      {heartRate > 0 && !scanning && (
        <div className="flex flex-col items-center justify-center flex-1 space-y-8 animate-in fade-in zoom-in duration-500">
          <div className="text-center">
