          <p className="text-gray-500 dark:text-gray-400 font-medium">Genotype: <span className="text-blue-600">{user.genotype}</span> • Blood Group: <span className="text-red-600">{user.bloodGroup}</span></p>
        </div>
        <div className="flex gap-2">
           <div className="bg-white dark:bg-gray-800 p-3 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-3 transition-colors">
             <div className="p-2 bg-blue-50 dark:bg-blue-900/30 text-blue-600 rounded-lg"><MapPin size={20}/></div>
             <div>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Live Location</p>
               <p className="text-sm font-semibold dark:text-gray-100">{location}</p>
             </div>
           </div>
        </div>
      </header>

      {/* Metric Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <MetricCard 
          title="Heart Rate" 
          value={`${lastMetric.heartRate} BPM`} 
          sub="Resting" 
          icon={<Heart className="text-red-500" />} 
          trend="+2%"
          color="bg-red-50 dark:bg-red-900/20"
        />
        <MetricCard 
          title="Steps" 
          value={steps.toLocaleString()} 
          sub={`Goal: ${stepGoal.toLocaleString()}`} 
          icon={<Footprints className="text-green-500" />} 
          trend={`${stepProgress}%`}
          color="bg-green-50 dark:bg-green-900/20"
        />
        <MetricCard 
          title="Stress Level" 
          value={lastMetric.stressLevel} 
          sub="Based on scan" 
          icon={<Zap className="text-yellow-500" />} 
          trend="Normal"
          color="bg-yellow-50 dark:bg-yellow-900/20"
        />
        <MetricCard 
          title="Blood Pressure" 
          value={lastMetric.bloodPressure} 
          sub="Latest check" 
          icon={<Activity className="text-blue-500" />} 
          trend="Steady"
          color="bg-blue-50 dark:bg-blue-900/20"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Activity Chart */}
        <div className="lg:col-span-2 bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 transition-colors">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold dark:text-white">Health Activity</h2>
            <div className="text-xs font-bold text-gray-400 bg-gray-50 dark:bg-gray-700 px-3 py-1 rounded-full">SIMULATED DATA</div>
          </div>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorHr" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} dy={10} />
                <YAxis hide />
                <Tooltip 
