import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Send, ArrowLeft, Bot, User, Mic, Speaker, PlayCircle } from 'lucide-react';
import { UserProfile, Message, AssistantType } from '../types';
import { gemini } from '../services/gemini';
import { SYSTEM_PROMPTS } from '../constants';

interface Props {
  user: UserProfile;
}

const Assistant: React.FC<Props> = ({ user }) => {
  const { type } = useParams<{ type: string }>();
  const navigate = useNavigate();
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const assistantConfig = {
    nurse: { title: 'Nurse Genova', role: AssistantType.NURSE, prompt: SYSTEM_PROMPTS.NURSE, color: 'bg-blue-600' },
    nutritionist: { title: 'Genova Nutrition', role: AssistantType.NUTRITIONIST, prompt: SYSTEM_PROMPTS.NUTRITIONIST, color: 'bg-orange-600' },
    fitness: { title: 'Genova Fitness', role: AssistantType.FITNESS, prompt: SYSTEM_PROMPTS.FITNESS, color: 'bg-green-600' },
    mental: { title: 'Wellness Guide', role: AssistantType.MENTAL, prompt: SYSTEM_PROMPTS.WELLNESS, color: 'bg-purple-600' },
  }[type || 'nurse'] || { title: 'Assistant', role: AssistantType.NURSE, prompt: SYSTEM_PROMPTS.NURSE, color: 'bg-blue-600' };

  useEffect(() => {
    // Welcome message
    const welcome = `Hello ${user.fullName.split(' ')[0]}, I'm your ${assistantConfig.title}. How can I help you with your ${type === 'nutritionist' ? 'diet' : 'health'} today?`;
    setMessages([{ role: 'model', text: welcome, timestamp: new Date() }]);
  }, [type, user.fullName]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg: Message = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      const response = await gemini.getResponse(
        'gemini-3-flash-preview',
        assistantConfig.prompt + `\nUser Context: Name=${user.fullName}, Age=${user.age}, Blood=${user.bloodGroup}, Genotype=${user.genotype}, Allergies=${user.allergies.join(',')}`,
        messages,
        input
      );

      const botMsg: Message = { role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, botMsg]);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'model', text: "I'm having trouble connecting. Please check your network.", timestamp: new Date() }]);
    } finally {
      setLoading(false);
    }
  };

  const speak = (text: string) => {
    const utterance = new SpeechSynthesisUtterance(text);
    window.speechSynthesis.speak(utterance);
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 dark:bg-gray-900 max-w-4xl mx-auto shadow-2xl transition-colors">
      {/* Header */}
      <header className={`${assistantConfig.color} p-4 md:p-6 text-white flex items-center gap-4 sticky top-0 z-10 shadow-lg`}>
        <button onClick={() => navigate('/')} className="hover:bg-white/20 p-2 rounded-full transition-colors">
          <ArrowLeft size={24} />
        </button>
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center backdrop-blur-md">
            <Bot size={24} />
          </div>
          <div>
            <h1 className="font-bold text-lg">{assistantConfig.title}</h1>
            <div className="flex items-center gap-1">
              <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></span>
              <span className="text-[10px] font-bold uppercase tracking-wider opacity-80">AI Active</span>
            </div>
          </div>
        </div>
      </header>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6 bg-white dark:bg-gray-900 transition-colors">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] flex flex-col gap-1 ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`px-5 py-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                m.role === 'user' 
                ? `${assistantConfig.color} text-white rounded-tr-none` 
                : 'bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-100 rounded-tl-none border border-gray-200 dark:border-gray-700'
              }`}>
                {m.text}
                {m.role === 'model' && (
                  <button onClick={() => speak(m.text)} className="mt-2 block text-xs opacity-60 hover:opacity-100">
                    <Speaker size={14} className="inline mr-1" /> Listen
                  </button>
                )}
              </div>
              <span className="text-[10px] text-gray-400 dark:text-gray-500 font-bold">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-gray-100 dark:bg-gray-800 px-5 py-3 rounded-2xl rounded-tl-none border border-gray-200 dark:border-gray-700">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              </div>
            </div>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      {/* Input */}
      <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-200 dark:border-gray-700 sticky bottom-0 transition-colors">
        <div className="flex gap-2 max-w-4xl mx-auto items-center">
          <button className="p-3 text-gray-400 dark:text-gray-500 hover:text-blue-600 transition-colors">
            <Mic size={24} />
          </button>
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type symptoms or questions..."
            className="flex-1 bg-gray-100 dark:bg-gray-700 border-none rounded-2xl px-5 py-3 focus:ring-2 focus:ring-blue-500 transition-all text-sm outline-none text-gray-900 dark:text-gray-100"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || loading}
            className={`${assistantConfig.color} text-white p-3 rounded-2xl disabled:opacity-50 transition-all active:scale-95`}
          >
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default Assistant;

