                <button type="button" onClick={back} className="flex-1 bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400 py-4 rounded-2xl font-bold">Back</button>
                <button type="submit" className="flex-[2] bg-blue-600 text-white py-4 rounded-2xl font-black shadow-xl shadow-blue-200 dark:shadow-none">Complete Profile</button>
              </div>
            </div>
          )}
        </form>
      </div>
    </div>
  );
};

