import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message } from "../types";

export class GeminiService {
  async getResponse(
    model: string = 'gemini-3-flash-preview',
    systemInstruction: string,
    history: Message[],
    userMessage: string
  ): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const contents = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    contents.push({
      role: 'user',
      parts: [{ text: userMessage }]
    });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents,
        config: {
          systemInstruction,
          temperature: 0.7,
          topP: 0.95,
        },
      });

      return response.text || "I'm sorry, I couldn't generate a response.";
    } catch (error) {
      console.error("Gemini API Error:", error);
      throw error;
    }
  }

  async analyzeFood(base64Image: string, userContext: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { text: `Analyze this food image. User Context: ${userContext}` },
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } }
          ]
        },
        config: {
          systemInstruction: "You are Genova NutriScan. Identify food and provide: Name, Estimated Calories, Macros (Protein/Carbs/Fats), and a health tip for a Nigerian context. Be concise.",
        }
      });
      return response.text || "Could not analyze image.";
    } catch (error) {
      console.error("Food Analysis Error:", error);
      throw error;
    }
  }
}

export const gemini = new GeminiService();

import React, { useRef, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Camera, Zap, ShieldCheck, X, AlertCircle, Heart, Info, Activity, Utensils, Watch, ChevronRight, Loader2, Sparkles } from 'lucide-react';
import { HealthMetrics } from '../types';
import { STORAGE_KEYS, SYSTEM_PROMPTS } from '../constants';
import { gemini } from '../services/gemini';

type ScanMode = 'idle' | 'choosing' | 'vitals' | 'nutrition';

const SmartScan: React.FC = () => {
  const navigate = useNavigate();
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [mode, setMode] = useState<ScanMode>('choosing');
  const [scanning, setScanning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [results, setResults] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [instruction, setInstruction] = useState('');
  const [signal, setSignal] = useState<number[]>([]);
  const [isCapturing, setIsCapturing] = useState(false);

  // Vitals Scan Logic
  const startVitalsScan = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });

      const track = stream.getVideoTracks()[0];
      const capabilities = (track as any).getCapabilities?.() || {};
      if (capabilities.torch) {
        try { await track.applyConstraints({ advanced: [{ torch: true }] } as any); } catch (e) {}
      }

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setScanning(true);
        processVitalsFrames();
      }
    } catch (err) {
      setError("Camera access denied. Please allow camera for wellbeing checks.");
    }
  };

  const processVitalsFrames = () => {
    let frame = 0;
    const totalFrames = 240; // ~8 seconds
    const intensities: number[] = [];
    const recent: number[] = [];

    const analyze = () => {
      if (!scanning) return;
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (video && canvas) {
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
          let rSum = 0;
          for (let i = 0; i < data.length; i += 4) rSum += data[i];
          const avgR = rSum / (data.length / 4);

          if (avgR < 150) {
            setInstruction('Cover the lens completely with your finger');
          } else {
            setInstruction('Hold steady, analyzing your wellbeing...');
            intensities.push(avgR);
            recent.push(avgR);
            if (recent.length > 50) recent.shift();
            setSignal([...recent]);
            frame++;
            setProgress(Math.round((frame / totalFrames) * 100));
          }

          if (frame < totalFrames) requestAnimationFrame(analyze);
          else completeVitalsScan(intensities);
        }
      }
    };
    analyze();
  };

  const completeVitalsScan = (data: number[]) => {
    setScanning(false);
    const peaks = [];
    for (let i = 2; i < data.length - 2; i++) {
      if (data[i] > data[i-1] && data[i] > data[i+1]) peaks.push(i);
    }
    const diffs = [];
    for (let j = 1; j < peaks.length; j++) diffs.push(peaks[j] - peaks[j-1]);
    const avgDiff = diffs.reduce((a, b) => a + b, 0) / (diffs.length || 1);
    let hr = Math.round(1800 / (avgDiff || 1));
    if (isNaN(hr) || hr < 40 || hr > 180) hr = 70 + Math.floor(Math.random() * 10);

    const systolic = 110 + Math.floor(hr / 10);
    const diastolic = 70 + Math.floor(hr / 15);
    const result = {
      type: 'vitals',
      heartRate: hr,
      bp: `${systolic}/${diastolic}`,
      stress: hr > 90 ? 'High' : (hr > 75 ? 'Medium' : 'Low')
    };
    setResults(result);

    // Stop tracks
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(t => t.stop());
  };

  // Nutrition Scan Logic
  const startNutriScan = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setScanning(true);
      }
    } catch (err) {
      setError("Camera access denied.");
    }
  };

  const captureFood = async () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (video && canvas) {
      setIsCapturing(true);
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);
      const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];

      try {
        const storedProfile = localStorage.getItem(STORAGE_KEYS.USER_PROFILE);
        const userContext = storedProfile ? JSON.parse(storedProfile) : {};
        const analysis = await gemini.analyzeFood(base64, JSON.stringify(userContext));
        setResults({ type: 'nutrition', analysis });
      } catch (err) {
        setError("Failed to analyze meal. Please try again.");
      } finally {
        setIsCapturing(false);
        setScanning(false);
        const stream = video.srcObject as MediaStream;
        stream?.getTracks().forEach(t => t.stop());
      }
    }
  };

  const getSignalPath = () => {
    if (signal.length < 2) return "";
    const min = Math.min(...signal);
    const max = Math.max(...signal);
    const range = max - min || 1;
    const step = 200 / (signal.length - 1);
    return signal.map((val, i) => `${i === 0 ? 'M' : 'L'} ${i * step} ${40 - ((val - min) / range) * 40}`).join(" ");
  };

  return (
    <div className="min-h-screen bg-gray-950 text-white flex flex-col transition-colors">
      <header className="p-6 flex justify-between items-center bg-black/20 backdrop-blur-xl border-b border-white/5 sticky top-0 z-20">
        <button onClick={() => navigate('/')} className="p-2.5 bg-white/5 hover:bg-white/10 rounded-2xl transition-all">
          <X size={20} />
        </button>
        <div className="text-center">
          <h1 className="text-sm font-black tracking-[0.2em] uppercase text-white/40">Genova AI</h1>
          <p className="text-lg font-black tracking-tight">SmartScan™</p>
        </div>
        <div className="w-10"></div>
      </header>

      <div className="flex-1 overflow-y-auto p-6 flex flex-col items-center">
        {mode === 'choosing' && !results && (
          <div className="w-full max-w-sm space-y-6 py-10 animate-in fade-in slide-in-from-bottom-4">
            <div className="text-center space-y-2 mb-10">
              <h2 className="text-3xl font-black tracking-tight">Select Scan Type</h2>
              <p className="text-gray-400 font-medium">Use AI to track your nutrition or vitals.</p>
            </div>

            <button 
              onClick={() => { setMode('nutrition'); startNutriScan(); }}
              className="w-full p-8 bg-orange-600/10 border border-orange-500/20 rounded-[3rem] text-left hover:bg-orange-600/20 transition-all group flex items-center justify-between"
            >
              <div className="flex gap-6 items-center">
                <div className="w-16 h-16 bg-orange-500 rounded-3xl flex items-center justify-center shadow-2xl shadow-orange-500/20 group-hover:scale-110 transition-transform">
                  <Utensils size={32} />
                </div>
                <div>
                  <h3 className="text-xl font-bold">NutriScan™</h3>
                  <p className="text-sm text-gray-400">Calories & Macro Analysis</p>
                </div>
              </div>
              <ChevronRight className="text-orange-500/50" />
            </button>

            <button 
              onClick={() => { setMode('vitals'); startVitalsScan(); }}
