  const [results, setResults] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [deviceConnected, setDeviceConnected] = useState(false);
  const [syncProgress, setSyncProgress] = useState(0);

  useEffect(() => {
    const savedDevice = localStorage.getItem(STORAGE_KEYS.WEARABLE_DEVICE);
    if (savedDevice) {
      setDeviceConnected(true);
    }
  }, []);

  // --- NUTRITION SCAN LOGIC (CAMERA) ---
  const startNutriCamera = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setMode('nutrition_camera');
      }
    } catch (err) {
      setError("Camera access is required for NutriScan™. Please check your browser permissions.");
