    history.push({
      heartRate: result.heartRate,
      bloodPressure: result.bp,
      stressLevel: result.stress,
      timestamp: new Date().toISOString()
    });
    localStorage.setItem(STORAGE_KEYS.HEALTH_HISTORY, JSON.stringify(history));
