                 <MacroCard label="Protein" value={results.protein} color="bg-blue-500/20 text-blue-400" />
                 <MacroCard label="Carbs" value={results.carbs} color="bg-green-500/20 text-green-400" />
                 <MacroCard label="Fat" value={results.fat} color="bg-yellow-500/20 text-yellow-400" />
               </div>

               <div className="p-8 bg-white/5 rounded-[2.5rem] border border-white/10">
                 <div className="flex items-center gap-3 mb-4">
                   <Sparkles className="text-blue-400" size={20} />
                   <h4 className="font-black text-xs uppercase tracking-[0.2em] text-white/60">Health Insight</h4>
                 </div>
                 <p className="text-gray-200 font-medium leading-relaxed">{results.healthTip}</p>
               </div>
             </div>
           )}

           <button 
             onClick={reset}
             className="w-full py-5 bg-white text-gray-950 rounded-[2rem] font-black text-lg active:scale-95 transition-all shadow-xl"
           >
             Continue Journey
           </button>
         </div>
        )}

        {error && (
          <div className="mt-10 p-6 bg-red-950/40 border border-red-900/40 rounded-3xl text-red-400 flex items-start gap-4">
            <AlertCircle className="shrink-0" />
            <div>
              <p className="font-bold">Scan Error</p>
              <p className="text-sm opacity-80">{error}</p>
              <button onClick={reset} className="mt-4 text-xs font-black uppercase tracking-widest text-white underline underline-offset-4">Try again</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const MacroCard: React.FC<{label: string, value: string, color: string}> = ({ label, value, color }) => (
  <div className={`p-4 rounded-3xl border border-white/5 text-center ${color}`}>
    <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-60">{label}</p>
    <p className="text-lg font-black">{value}</p>
  </div>
);

export default SmartScan;

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Send, ArrowLeft, Bot, Mic, Speaker, Stethoscope, Utensils, Activity, Brain, ClipboardList, Pill, Baby, MicOff, Crown } from 'lucide-react';
import { UserProfile, Message, AssistantType, HealthMetrics } from '../types';
import { gemini } from '../services/gemini';
import { SYSTEM_PROMPTS, STORAGE_KEYS } from '../constants';

interface Props {
  user: UserProfile;
}

const Assistant: React.FC<Props> = ({ user }) => {
  const { type } = useParams<{ type: string }>();
  const navigate = useNavigate();
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const isPremium = user.subscriptionStatus === 'premium';

  useEffect(() => {
    if (type === 'family' && !isPremium) {
      navigate('/premium');
    }
  }, [type, isPremium, navigate]);

  const assistantConfig = {
    nurse: { 
      title: 'Nurse Genova', 
      role: AssistantType.NURSE, 
      prompt: SYSTEM_PROMPTS.NURSE, 
      color: 'bg-blue-600', 
      icon: <Stethoscope size={24} />,
      placeholder: 'Describe how you feel...'
    },
    nutritionist: { 
      title: 'Genova Nutrition', 
      role: AssistantType.NUTRITIONIST, 
      prompt: SYSTEM_PROMPTS.NUTRITIONIST, 
      color: 'bg-orange-500', 
      icon: <Utensils size={24} />,
      placeholder: 'Ask about Nigerian meal plans...'
    },
    fitness: { 
      title: 'Fitness Coach', 
      role: AssistantType.FITNESS, 
      prompt: SYSTEM_PROMPTS.FITNESS, 
      color: 'bg-green-600', 
      icon: <Activity size={24} />,
      placeholder: 'Ask for a home workout...'
    },
    mental: { 
      title: 'Wellness Guide', 
      role: AssistantType.MENTAL, 
      prompt: SYSTEM_PROMPTS.WELLNESS, 
      color: 'bg-purple-600', 
      icon: <Brain size={24} />,
      placeholder: 'Talk about your mood or stress...'
    },
    symptom: { 
      title: 'Symptom Checker', 
      role: AssistantType.SYMPTOM_CHECKER, 
      prompt: SYSTEM_PROMPTS.SYMPTOM_CHECKER, 
      color: 'bg-red-500', 
      icon: <ClipboardList size={24} />,
      placeholder: 'List your symptoms (e.g. fever, headache)...'
    },
    prescription: { 
      title: 'Medication Explainer', 
      role: AssistantType.NURSE, 
      prompt: SYSTEM_PROMPTS.PRESCRIPTION, 
      color: 'bg-indigo-600', 
      icon: <Pill size={24} />,
      placeholder: 'Enter drug name (e.g. Lonart, Paracetamol)...'
    },
    family: {
      title: 'Family Health',
      role: AssistantType.FAMILY,
      prompt: SYSTEM_PROMPTS.FAMILY,
      color: 'bg-pink-500',
      icon: <Baby size={24} />,
      placeholder: 'Ask about baby care or growth...'
    }
  }[type || 'nurse'] || { 
    title: 'Genova AI', 
    role: AssistantType.NURSE, 
    prompt: SYSTEM_PROMPTS.NURSE, 
    color: 'bg-blue-600', 
    icon: <Bot size={24} />,
    placeholder: 'How can I help?'
  };

  useEffect(() => {
    const welcomeMessages: Record<string, string> = {
      nurse: `Hi ${user.fullName.split(' ')[0]}, I'm Nurse Genova. How are you feeling today?`,
      nutritionist: `Hello! I can help you create a meal plan tailored for ${user.genotype} genotype. What's on the menu?`,
      fitness: `Ready to get active? I can suggest exercises for your weight (${user.weight}kg) and goals.`,
      mental: `Take a deep breath. I'm here to support your mental wellness. How's your mood?`,
      symptom: `Let's analyze your symptoms. Please be descriptive about how you feel.`,
      prescription: `I can explain how your medications work. Which drug are you taking?`,
      family: `Hi! I'm here for you and your family's health. Ask me about baby growth, immunizations, or child nutrition.`
    };

    setMessages([{ 
      role: 'model', 
      text: welcomeMessages[type || 'nurse'] || welcomeMessages.nurse, 
      timestamp: new Date() 
    }]);
  }, [type, user.fullName, user.genotype, user.weight]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (overrideInput?: string) => {
    const messageText = overrideInput || input;
    if (!messageText.trim() || loading) return;

    const userMsg: Message = { role: 'user', text: messageText, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    const storedHistory = localStorage.getItem(STORAGE_KEYS.HEALTH_HISTORY);
    const lastMetric: HealthMetrics | null = storedHistory ? JSON.parse(storedHistory).pop() : null;
    const biometricContext = lastMetric ? `\nLATEST BIOMETRICS: HR=${lastMetric.heartRate} BPM, BP=${lastMetric.bloodPressure}.` : '';

    try {
      const response = await gemini.getResponse(
        'gemini-3-flash-preview',
        assistantConfig.prompt + `\n\nUSER MEDICAL PROFILE:\nName: ${user.fullName}\nAge: ${user.age}\nGender: ${user.gender}\nGenotype: ${user.genotype}\nBlood Group: ${user.bloodGroup}\nAllergies: ${user.allergies.join(', ') || 'None'}\nWeight: ${user.weight}kg\nHeight: ${user.height}cm` + biometricContext,
        messages,
        messageText
      );

      const botMsg: Message = { role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, botMsg]);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'model', text: "Connection error. Please try again.", timestamp: new Date() }]);
    } finally {
      setLoading(false);
    }
  };

  const startVoiceInput = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice recognition not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-NG'; 
    recognition.start();
    setIsListening(true);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(transcript);
      setIsListening(false);
      handleSend(transcript);
    };

    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => setIsListening(false);
  };

  const speak = (text: string) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.rate = 1.0;
    window.speechSynthesis.speak(utterance);
  };

  return (
    <div className="flex flex-col h-screen bg-white dark:bg-gray-950 max-w-4xl mx-auto transition-colors">
      <header className={`${assistantConfig.color} p-4 md:p-6 text-white flex items-center justify-between sticky top-0 z-10 shadow-xl`}>
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/')} className="hover:bg-white/20 p-2 rounded-full transition-colors">
            <ArrowLeft size={24} />
          </button>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center backdrop-blur-md">
              {assistantConfig.icon}
            </div>
            <div>
              <h1 className="font-bold text-lg flex items-center gap-2">
                {assistantConfig.title}
                {isPremium && <Crown size={14} className="text-amber-300" />}
              </h1>
              <div className="flex items-center gap-1">
                <span className={`w-2 h-2 rounded-full ${isListening ? 'bg-red-400 animate-ping' : 'bg-green-400 animate-pulse'}`}></span>
                <span className="text-[10px] font-bold uppercase tracking-widest opacity-80">
                  {isListening ? 'Listening...' : 'AI Active'}
                </span>
              </div>
            </div>
          </div>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 bg-gray-50 dark:bg-gray-900 transition-colors">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2`}>
            <div className={`max-w-[85%] flex flex-col gap-1 ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`px-5 py-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                m.role === 'user' 
                ? `${assistantConfig.color} text-white rounded-tr-none` 
                : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 rounded-tl-none border border-gray-100 dark:border-gray-700'
              }`}>
                {m.text}
                {m.role === 'model' && (
                  <button 
                    onClick={() => speak(m.text)} 
                    className="mt-3 flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider opacity-60 hover:opacity-100 transition-opacity bg-black/5 dark:bg-white/5 px-2 py-1 rounded-lg"
                  >
                    <Speaker size={12} /> Read Aloud
                  </button>
                )}
              </div>
              <span className="text-[10px] text-gray-400 dark:text-gray-500 font-bold px-1">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-white dark:bg-gray-800 px-5 py-3 rounded-2xl rounded-tl-none border border-gray-100 dark:border-gray-700 shadow-sm">
              <div className="flex gap-1.5">
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              </div>
            </div>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-700 sticky bottom-0 transition-colors">
        <div className="flex gap-2 max-w-4xl mx-auto items-center">
          <button 
            onClick={startVoiceInput}
            className={`p-3 rounded-full transition-all ${isListening ? 'bg-red-500 text-white animate-pulse' : 'text-gray-400 dark:text-gray-500 hover:text-blue-500'}`}
          >
            {isListening ? <MicOff size={24} /> : <Mic size={24} />}
          </button>
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder={assistantConfig.placeholder}
            className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-2xl px-5 py-3.5 focus:ring-2 focus:ring-blue-500 transition-all text-sm outline-none text-gray-900 dark:text-gray-100 shadow-inner"
          />
          <button 
            onClick={() => handleSend()}
            disabled={!input.trim() || loading}
            className={`${assistantConfig.color} text-white p-3.5 rounded-2xl disabled:opacity-50 transition-all active:scale-90 shadow-lg`}
          >
            <Send size={22} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default Assistant;

import React, { useState, useEffect, useRef } from 'react';
import { Bluetooth, Watch, Activity, Battery, CheckCircle2, XCircle, AlertCircle, RefreshCw, ChevronLeft, Zap, Crown } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { STORAGE_KEYS } from '../constants';
import { UserProfile } from '../types';

interface Props {
  user: UserProfile;
}

const Wearables: React.FC<Props> = ({ user }) => {
  const navigate = useNavigate();
  const [isScanning, setIsScanning] = useState(false);
  const [device, setDevice] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [liveHr, setLiveHr] = useState(72);
  const [liveBattery, setLiveBattery] = useState(88);
  const intervalRef = useRef<number | null>(null);

  const isPremium = user.subscriptionStatus === 'premium';

  useEffect(() => {
    const savedDevice = localStorage.getItem(STORAGE_KEYS.WEARABLE_DEVICE);
    if (savedDevice) {
      setDevice(JSON.parse(savedDevice));
    }
  }, []);

  useEffect(() => {
    if (device && device.connected) {
      intervalRef.current = window.setInterval(() => {
        setLiveHr(prev => {
          const change = Math.floor(Math.random() * 3) - 1; 
          const newHr = prev + change;
          return Math.min(Math.max(newHr, 60), 100);
        });
        setLiveBattery(prev => Math.max(prev - (Math.random() > 0.95 ? 1 : 0), 1));
      }, 2000);
    } else {
      if (intervalRef.current) clearInterval(intervalRef.current);
    }
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [device]);

  const requestBluetooth = async () => {
    if (!isPremium) {
      navigate('/premium');
      return;
    }
    setIsScanning(true);
    setError(null);
    try {
      const bluetooth = (navigator as any).bluetooth;
      if (!bluetooth) {
        throw new Error("Web Bluetooth is not supported in this browser.");
      }

      const btDevice = await bluetooth.requestDevice({
        acceptAllDevices: true,
        optionalServices: ['heart_rate', 'battery_service']
      });

      const deviceData = {
        name: btDevice.name || 'Genova SmartBand',
        id: btDevice.id,
        connected: true,
        lastSeen: new Date().toISOString()
      };

      setDevice(deviceData);
      localStorage.setItem(STORAGE_KEYS.WEARABLE_DEVICE, JSON.stringify(deviceData));

      if (btDevice.gatt) {
        await btDevice.gatt.connect();
      }

    } catch (err: any) {
      if (err.name !== 'NotFoundError' && err.name !== 'AbortError') {
        setError(err.message || "Failed to connect to device.");
      }
    } finally {
      setIsScanning(false);
    }
  };

  const disconnect = () => {
    setDevice(null);
    localStorage.removeItem(STORAGE_KEYS.WEARABLE_DEVICE);
    setLiveHr(72);
    setLiveBattery(88);
  };

  return (
    <div className="p-4 md:p-10 max-w-4xl mx-auto space-y-8 animate-in fade-in duration-500 pb-24 md:pb-10">
      <header className="flex items-center gap-4">
        <button onClick={() => navigate('/')} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors text-gray-900 dark:text-white">
          <ChevronLeft size={24} />
        </button>
        <div>
          <h1 className="text-3xl font-black text-gray-900 dark:text-white tracking-tight flex items-center gap-2">
            Connect Wearables
            {!isPremium && <Crown size={20} className="text-amber-500" />}
          </h1>
          <p className="text-gray-500 dark:text-gray-400 font-medium">Sync biometric data for deeper AI insights</p>
        </div>
      </header>

      {!isPremium && (
        <div className="bg-amber-500/10 border border-amber-500/20 p-6 rounded-3xl space-y-4">
           <div className="flex items-start gap-4">
              <div className="p-3 bg-amber-500 text-white rounded-2xl shadow-xl shadow-amber-500/20"><Crown size={24} /></div>
              <div>
                <h3 className="text-lg font-black text-amber-600">Premium Only</h3>
                <p className="text-sm text-amber-700/80 font-medium">Wearable synchronization is a Gold feature. Connect your Apple Watch, Fitbit, or Samsung Gear for real-time analysis.</p>
              </div>
           </div>
           <button onClick={() => navigate('/premium')} className="w-full bg-amber-500 text-white py-4 rounded-2xl font-black shadow-lg active:scale-95 transition-all">Upgrade Now</button>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 opacity-100">
        <div className={`bg-white dark:bg-gray-800 p-8 rounded-[40px] shadow-sm border border-gray-100 dark:border-gray-700 flex flex-col items-center justify-center text-center space-y-6 transition-colors ${!isPremium ? 'opacity-50 pointer-events-none' : ''}`}>
          {!device ? (
            <>
              <div className={`w-28 h-28 rounded-full flex items-center justify-center relative ${isScanning ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'bg-gray-100 dark:bg-gray-700 text-gray-400'}`}>
                <Bluetooth size={56} className={isScanning ? 'animate-pulse' : ''} />
                {isScanning && (
                  <div className="absolute inset-0 rounded-full border-4 border-blue-500 border-t-transparent animate-spin"></div>
                )}
              </div>
              <div className="space-y-2">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">{isScanning ? 'Searching for devices...' : 'No device connected'}</h2>
                <p className="text-sm text-gray-500 dark:text-gray-400 px-8">Enable Bluetooth and place your fitness tracker in pairing mode near your phone.</p>
              </div>

              {error && (
                <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-4 rounded-2xl text-xs flex items-start gap-3 border border-red-100 dark:border-red-900/30 text-left">
                  <AlertCircle size={18} className="shrink-0" />
                  <span>{error}</span>
                </div>
              )}

              <button 
                onClick={requestBluetooth}
                disabled={isScanning}
                className="w-full bg-blue-600 text-white py-4 rounded-3xl font-black text-lg shadow-xl shadow-blue-200 dark:shadow-none hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                {isScanning ? <RefreshCw className="animate-spin" /> : <Bluetooth />}
                {isScanning ? 'Scanning...' : 'Pair New Device'}
              </button>
            </>
          ) : (
            <>
              <div className="relative">
                <div className="w-28 h-28 bg-green-100 dark:bg-green-900/30 text-green-600 rounded-full flex items-center justify-center shadow-inner">
                  <Watch size={56} />
                </div>
                <div className="absolute -bottom-1 -right-1 bg-green-500 text-white p-1.5 rounded-full border-4 border-white dark:border-gray-800">
                  <CheckCircle2 size={16} />
                </div>
              </div>

              <div className="space-y-1">
                <h2 className="text-2xl font-black text-gray-900 dark:text-white tracking-tight">{device.name}</h2>
                <div className="flex items-center justify-center gap-2">
                  <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                  <p className="text-green-600 dark:text-green-400 font-black uppercase tracking-widest text-[10px]">Active Connection</p>
                </div>
              </div>

              <div className="w-full grid grid-cols-2 gap-4">
                <div className="bg-gray-50 dark:bg-gray-900 p-5 rounded-3xl text-left border border-gray-100 dark:border-gray-700 shadow-sm transition-colors">
                  <div className="flex items-center justify-between mb-2">
                    <Battery className={liveBattery > 20 ? "text-green-500" : "text-red-500"} size={20} />
                    <span className="text-[10px] font-black text-gray-400 uppercase">Power</span>
                  </div>
                  <p className="text-2xl font-black text-gray-900 dark:text-white">{liveBattery}%</p>
                </div>
                <div className="bg-gray-50 dark:bg-gray-900 p-5 rounded-3xl text-left border border-gray-100 dark:border-gray-700 shadow-sm transition-colors">
                  <div className="flex items-center justify-between mb-2">
                    <Activity className="text-red-500 pulse-red" size={20} />
                    <span className="text-[10px] font-black text-gray-400 uppercase">HR Stream</span>
                  </div>
                  <p className="text-2xl font-black text-gray-900 dark:text-white">{liveHr} <span className="text-sm font-bold text-gray-400">BPM</span></p>
                </div>
              </div>

              <div className="w-full space-y-3">
                <button 
                  onClick={disconnect}
                  className="w-full bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 py-4 rounded-3xl font-bold flex items-center justify-center gap-2 hover:bg-red-50 dark:hover:bg-red-900/20 hover:text-red-600 transition-all border border-transparent hover:border-red-100 dark:hover:border-red-900/30"
                >
                  <XCircle size={20} />
                  Unpair Device
                </button>
              </div>
            </>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-indigo-600 p-8 rounded-[40px] text-white space-y-5 shadow-xl relative overflow-hidden group">
            <Zap className="absolute -right-4 -top-4 w-24 h-24 text-white/10 group-hover:scale-110 transition-transform duration-500" />
            <h2 className="text-xl font-bold relative z-10">Smart Health Sync</h2>
            <ul className="space-y-5 relative z-10">
              <li className="flex gap-4">
                <div className="bg-white/20 p-2.5 rounded-xl h-fit shadow-sm"><Activity size={18} /></div>
                <p className="text-sm font-medium leading-relaxed">Continuous heart rate data allows the AI Nurse to spot cardiovascular trends before they become symptoms.</p>
              </li>
              <li className="flex gap-4">
                <div className="bg-white/20 p-2.5 rounded-xl h-fit shadow-sm"><CheckCircle2 size={18} /></div>
                <p className="text-sm font-medium leading-relaxed">Sleep cycles and activity levels are automatically factored into your personalized workout intensity.</p>
              </li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Wearables;

