        <div className="flex items-center gap-4">
          <div className="glass px-6 py-3 rounded-[1.5rem] border border-slate-200 dark:border-slate-800 flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-500/10 text-blue-600 rounded-xl flex items-center justify-center"><MapPin size={16}/></div>
            <div>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Location</p>
              <p className="text-xs font-black dark:text-slate-100">{location}</p>
            </div>
          </div>
        </div>
      </header>

      {/* Primary Bento Grid */}
      <div className="grid grid-cols-1 md:grid-cols-4 lg:grid-cols-6 gap-6">

        {/* Step Progress Card (Large) */}
        <div className="md:col-span-2 lg:col-span-2 bento-card bg-white dark:bg-slate-900 p-8 rounded-[3rem] shadow-sm relative overflow-hidden flex flex-col justify-between min-h-[320px]">
          <div className="relative z-10">
            <div className="flex justify-between items-start mb-6">
              <div className="p-4 bg-green-500/10 text-green-500 rounded-3xl"><Footprints size={28}/></div>
              <span className="text-sm font-black text-green-500">+{stepProgress}% today</span>
            </div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Activity Tracking</h3>
            <p className="text-5xl font-black tracking-tighter text-slate-950 dark:text-white">{steps.toLocaleString()}</p>
            <p className="text-sm text-slate-500 font-medium">Steps of {stepGoal.toLocaleString()} goal</p>
          </div>
          <div className="relative z-10 w-full h-3 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden mt-8">
            <div className="h-full bg-green-500 rounded-full transition-all duration-1000" style={{ width: `${stepProgress}%` }} />
          </div>
          <div className="absolute -right-12 -bottom-12 w-48 h-48 bg-green-500/5 rounded-full" />
        </div>

        {/* Heart Rate Card (Medium) */}
        <div className="md:col-span-2 lg:col-span-2 bento-card bg-slate-950 dark:bg-blue-600 p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden min-h-[320px] flex flex-col justify-between">
          <div className="relative z-10">
            <div className="flex justify-between items-start mb-6">
              <div className="p-4 bg-white/10 rounded-3xl backdrop-blur-md"><Heart className="text-white animate-pulse" size={28}/></div>
              <ArrowUpRight size={20} className="text-white/40" />
            </div>
            <h3 className="text-[10px] font-black text-white/50 uppercase tracking-widest mb-1">Vitality Engine</h3>
            <p className="text-6xl font-black tracking-tighter text-white">{lastMetric.heartRate}<span className="text-2xl ml-1 font-bold text-white/40">BPM</span></p>
          </div>
          <div className="relative z-10 flex gap-4">
             <div className="bg-white/10 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-white/10">RESTING</div>
