              <h2 className="text-2xl font-black tracking-tight dark:text-white">Activity Analysis</h2>
              <p className="text-sm text-slate-400 font-medium">Your biometric trends for the past 7 days</p>
            </div>
            <select className="bg-slate-50 dark:bg-slate-800 text-xs font-bold px-4 py-2 rounded-xl outline-none border-none">
