  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const isPremium = user.subscriptionStatus === 'premium';

  useEffect(() => {
    if (type === 'family' && !isPremium) {
      navigate('/premium');
    }
  }, [type, isPremium, navigate]);

  const assistantConfig = {
    nurse: { title: 'Nurse Genova', role: AssistantType.NURSE, prompt: SYSTEM_PROMPTS.NURSE, color: 'bg-blue-600', icon: <Stethoscope size={22} /> },
    nutritionist: { title: 'Nutritionist', role: AssistantType.NUTRITIONIST, prompt: SYSTEM_PROMPTS.NUTRITIONIST, color: 'bg-orange-500', icon: <Utensils size={22} /> },
    fitness: { title: 'Fitness Coach', role: AssistantType.FITNESS, prompt: SYSTEM_PROMPTS.FITNESS, color: 'bg-green-600', icon: <Activity size={22} /> },
    mental: { title: 'Wellness Guide', role: AssistantType.MENTAL, prompt: SYSTEM_PROMPTS.WELLNESS, color: 'bg-purple-600', icon: <Brain size={22} /> },
    symptom: { title: 'Symptom Checker', role: AssistantType.SYMPTOM_CHECKER, prompt: SYSTEM_PROMPTS.SYMPTOM_CHECKER, color: 'bg-red-500', icon: <ClipboardList size={22} /> },
    prescription: { title: 'Med Explainer', role: AssistantType.NURSE, prompt: SYSTEM_PROMPTS.PRESCRIPTION, color: 'bg-indigo-600', icon: <Pill size={22} /> },
    family: { title: 'Family Health', role: AssistantType.FAMILY, prompt: SYSTEM_PROMPTS.FAMILY, color: 'bg-pink-500', icon: <Baby size={22} /> }
  }[type || 'nurse'] || { title: 'Genova AI', role: AssistantType.NURSE, prompt: SYSTEM_PROMPTS.NURSE, color: 'bg-slate-900', icon: <Bot size={22} /> };

  useEffect(() => {
    const welcome = `Hi ${user.fullName.split(' ')[0]}, I'm your ${assistantConfig.title}. How can I assist with your health goals today?`;
    setMessages([{ role: 'model', text: welcome, timestamp: new Date() }]);
  }, [type, user.fullName]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;
    const text = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text, timestamp: new Date() }]);
    setLoading(true);

    try {
      const response = await gemini.getResponse(
        'gemini-3-flash-preview',
        assistantConfig.prompt + `\n\nUSER PROFILE: Gender=${user.gender}, Genotype=${user.genotype}, BloodGroup=${user.bloodGroup}, Allergies=${user.allergies.join(',')}`,
        messages,
        text
      );
      setMessages(prev => [...prev, { role: 'model', text: response, timestamp: new Date() }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: "Service temporarily unavailable. Check your connection.", timestamp: new Date() }]);
    } finally {
      setLoading(false);
    }
  };

  const startVoice = () => {
    const Recognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!Recognition) return alert("Browser not supported");
    const r = new Recognition();
    r.start(); setIsListening(true);
    r.onresult = (e: any) => { setInput(e.results[0][0].transcript); handleSend(); };
    r.onend = () => setIsListening(false);
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 dark:bg-[#020617] transition-colors md:pl-20">
      <header className="glass p-5 flex items-center justify-between border-b border-slate-200 dark:border-slate-800 sticky top-0 z-10">
        <div className="flex items-center gap-5">
          <button onClick={() => navigate('/')} className="p-2.5 bg-slate-100 dark:bg-slate-800 rounded-2xl">
            <ArrowLeft size={20} />
          </button>
          <div className="flex items-center gap-4">
            <div className={`w-12 h-12 ${assistantConfig.color} text-white rounded-2xl flex items-center justify-center shadow-lg shadow-black/10`}>
              {assistantConfig.icon}
            </div>
            <div>
              <h1 className="font-black text-lg tracking-tight dark:text-white flex items-center gap-2">
                {assistantConfig.title}
                {isPremium && <Crown size={14} className="text-amber-500" />}
              </h1>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Always Active</span>
            </div>
          </div>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 max-w-4xl mx-auto w-full">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
            <div className={`max-w-[85%] ${m.role === 'user' ? 'bg-slate-900 dark:bg-blue-600 text-white rounded-[2rem] rounded-tr-none' : 'bg-white dark:bg-slate-900 text-slate-800 dark:text-slate-100 rounded-[2rem] rounded-tl-none border border-slate-100 dark:border-slate-800 shadow-sm'} p-6`}>
              <p className="text-sm font-medium leading-relaxed">{m.text}</p>
              <div className="flex justify-between items-center mt-3 opacity-40">
                <span className="text-[9px] font-black uppercase tracking-widest">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                {m.role === 'model' && <Speaker size={12} className="cursor-pointer hover:scale-125 transition-transform" onClick={() => {
                  window.speechSynthesis.cancel();
                  window.speechSynthesis.speak(new SpeechSynthesisUtterance(m.text));
                }}/>}
              </div>
            </div>
          </div>
        ))}
        {loading && <div className="flex justify-start animate-pulse"><div className="bg-slate-200 dark:bg-slate-800 h-12 w-24 rounded-full" /></div>}
        <div ref={scrollRef} />
      </div>

      <div className="p-6 md:p-10 sticky bottom-0 bg-gradient-to-t from-slate-50 dark:from-[#020617] to-transparent">
        <div className="max-w-4xl mx-auto flex gap-4 items-center glass p-3 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-2xl">
          <button 
            onClick={startVoice}
            className={`p-4 rounded-3xl transition-all ${isListening ? 'bg-red-500 text-white animate-pulse' : 'text-slate-400 dark:text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            {isListening ? <MicOff size={24} /> : <Mic size={24} />}
          </button>
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type your health concern..."
            className="flex-1 bg-transparent border-none py-3 px-2 outline-none text-slate-900 dark:text-white font-medium placeholder:text-slate-400"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || loading}
            className={`${assistantConfig.color} text-white p-4 rounded-[1.75rem] shadow-xl active:scale-95 disabled:opacity-30 transition-all`}
          >
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default Assistant;

